<template>
  <section class="session-view" aria-live="polite">
    <q-banner v-if="error" rounded class="review-error q-mb-md">{{ error }}</q-banner>
    <template v-if="currentCard">
      <section class="session-progress" aria-label="Estado da fila"><div><span>Cards vencidos</span><q-linear-progress rounded size="8px" color="primary" track-color="blue-grey-10" :value="session?.overdueCards ? 1 : 0" /></div><strong>{{ session?.overdueCards ?? 0 }} pendente(s)</strong></section>
      <q-card flat class="flashcard-surface"><q-card-section class="flashcard-content"><div class="card-toolbar"><q-badge rounded class="card-count">Fila contínua</q-badge><q-badge rounded class="card-kind">{{ session?.kind === 'ADVANCE' ? 'Antecipada' : 'Revisão' }}</q-badge><q-space /><q-btn flat round dense icon="star_border" aria-label="Card da sessão" /></div><div class="card-copy"><p class="card-label">{{ revealed ? 'Resposta' : 'Lembre-se do conceito' }}</p><h2>{{ revealed ? currentCard.back : currentCard.front }}</h2></div><q-btn v-if="!revealed" unelevated no-caps icon="visibility" label="Toque para ver a resposta" class="reveal-button" @click="revealed = true"/><p v-else class="rating-prompt"><q-icon name="psychology" size="17px" /> Como foi lembrar deste card?</p></q-card-section></q-card>
      <section v-if="revealed && !session?.currentCardReviewed" class="rating-grid" aria-label="Classifique sua lembrança"><q-btn v-for="item in ratings" :key="item.value" unelevated no-caps text-color="white" :style="'background: ' + item.background + ' !important; color: #fff !important;'" :loading="loading" :disable="loading" class="rating-button" @click="submit(item.value)"><q-icon :name="item.icon" size="27px" /><span>{{ item.label }}</span><small>{{ item.hint }}</small></q-btn></section>
      <p v-if="revealed && session?.currentCardReviewed" class="rating-prompt">Este card já foi classificado nesta sessão.</p><footer class="session-footer"><q-btn flat no-caps icon="chevron_left" label="Anterior" :disable="loading || !session?.canGoPrevious" @click="move('PREVIOUS')"/><span>Você pode navegar sem classificar.</span><q-btn flat no-caps icon-right="chevron_right" label="Próximo" :disable="loading || !session?.canGoNext" @click="move('NEXT')"/></footer>
    </template>
    <q-card v-else-if="!loading" flat class="session-empty"><q-card-section><q-icon name="task_alt" size="34px" color="positive" /><h2>Nenhum card vencido</h2><p>Você está em dia com suas revisões.</p><q-btn v-if="session?.canAdvance" unelevated no-caps color="primary" class="q-mt-md" icon="fast_forward" label="Adiantar revisões" @click="load('advance')"/></q-card-section></q-card>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useReview } from './useReview'
const { error, loading, loadSession, navigate, rate, session } = useReview()
const revealed = ref(false)
const currentCard = computed(() => session.value?.cards[0] ?? null)
const ratings = [{ value: 'AGAIN', label: 'Não lembrei', hint: '1', icon: 'sentiment_very_dissatisfied', background: '#b94759' }, { value: 'HARD', label: 'Difícil', hint: '2', icon: 'sentiment_dissatisfied', background: '#ad6635' }, { value: 'GOOD', label: 'Lembrei', hint: '3', icon: 'sentiment_satisfied', background: '#2378bb' }, { value: 'EASY', label: 'Fácil', hint: '4', icon: 'sentiment_very_satisfied', background: '#219d76' }] as const
async function load(kind: 'daily' | 'quick' | 'advance' = 'daily'): Promise<void> { await loadSession(kind); revealed.value = false }
async function submit(value: typeof ratings[number]['value']): Promise<void> { if (!session.value || !currentCard.value) return; if (await rate(session.value.id, currentCard.value.id, value)) revealed.value = false }
async function move(direction: 'NEXT' | 'PREVIOUS'): Promise<void> { if (!session.value || await navigate(session.value.id, direction)) revealed.value = false }
defineExpose({ load })
onMounted(() => void load())
</script>

<style scoped>
.session-view{max-width:760px;margin:0 auto}.review-error{background:rgba(111,32,47,.42);border:1px solid rgba(255,118,107,.55);color:#ffd8d4}.session-progress{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;align-items:end;margin:22px 0 17px;color:#90a9cc}.session-progress span{display:block;margin-bottom:8px;font-size:12px;font-weight:700}.session-progress strong{color:#65b6ff;font-size:13px}.flashcard-surface{overflow:hidden;min-height:334px;border:1px solid #1c426d!important;border-radius:20px!important;background:radial-gradient(circle at 100% 100%,rgba(30,113,218,.17),transparent 35%),linear-gradient(145deg,#102b4c,#0a1d35)!important;box-shadow:0 22px 46px rgba(0,0,0,.25)!important}.flashcard-content{display:flex;min-height:334px;flex-direction:column;padding:20px 28px!important}.card-toolbar{display:flex;align-items:center;gap:8px}.card-count,.card-kind{padding:5px 10px;background:#102f53;color:#d9edff;font-size:11px;font-weight:750}.card-kind{background:#1761a2;color:#dff3ff}.card-toolbar :deep(.q-btn){color:#c3dcff}.card-copy{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:28px 5px}.card-label{margin:0 0 9px;color:#78baff;font-size:12px;font-weight:750;letter-spacing:.05em;text-transform:uppercase}.card-copy h2{max-width:100%;margin:0;color:#f3f8ff;font-size:clamp(27px,5vw,46px);font-weight:730;line-height:1.13;letter-spacing:-.035em;overflow-wrap:anywhere}.reveal-button{align-self:center;min-height:40px;padding:0 18px;border-radius:22px;background:#17385e!important;color:#d8eaff!important;font-size:12px}.rating-prompt{display:flex;align-self:center;align-items:center;gap:7px;margin:0;color:#9ec7f6;font-size:12px}.rating-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:17px}.rating-button{min-height:79px;padding:10px 8px;border-radius:12px;border:1px solid rgba(255,255,255,.22);font-size:12px;font-weight:760;line-height:1.1}.rating-button :deep(.q-btn__content){display:flex;flex-direction:column;gap:4px}.rating-button small{font-size:10px;opacity:.72}.rating-button:hover{filter:brightness(1.12)}.session-footer{display:flex;align-items:center;justify-content:space-between;margin-top:12px}.session-footer :deep(.q-btn){color:#a9c4e8;font-size:12px}.page-dots{display:flex;gap:5px;max-width:45%;overflow:hidden}.page-dots span{width:7px;height:7px;flex:0 0 7px;border-radius:50%;background:#294969}.page-dots .active{background:#65b6ff;box-shadow:0 0 0 3px rgba(101,182,255,.15)}.session-empty{text-align:center;border-radius:18px!important;background:#0c1b31!important}.session-empty :deep(.q-card__section){padding:50px 28px}.session-empty h2{margin:14px 0 7px;color:#eaf4ff}.session-empty p{margin:0;color:#92a9c9}@media(max-width:599px){.session-progress{margin-top:16px}.flashcard-surface,.flashcard-content{min-height:286px}.flashcard-content{padding:16px!important}.card-copy{padding:20px 2px}.rating-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.rating-button{min-height:74px;padding:10px 12px;text-align:left}.rating-button :deep(.q-btn__content){display:grid;grid-template-columns:28px minmax(0,1fr);align-items:center;gap:9px;width:100%;font-size:13px}.rating-button :deep(.q-icon){font-size:25px!important}.rating-button small{display:none}.session-footer{margin-bottom:4px}.page-dots{max-width:32%}.session-footer :deep(.q-btn){padding:5px}.session-footer :deep(.q-btn__content){font-size:0}.session-footer :deep(.q-icon){font-size:20px}}
</style>
